class Cat {
    private int fish;

    public void setFish(int fish) {
        if (fish < 0) {
            System.out.println("不能是负的喵");
            return;
        }
        this.fish = fish;
    }

    public int getFish() {
        return fish;
    }
}

public class Main {
    public static void main(String[] args) {
        Cat c = new Cat();
        c.setFish(-2);
        c.setFish(5);
        System.out.println(c.getFish());
    }
}

class Cat {
    private String name;
    private int fish;

    Cat(String name, int fish) {
        this.name = name;
        this.fish = fish;
    }

    public String report() {
        return name + " 有 " + fish + " 条小鱼干";
    }
}

public class Main {
    public static void main(String[] args) {
        Cat c = new Cat("小橘", 3);
        System.out.println(c.report());
    }
}
